using OcctSharp.Generator.Emission;
using OcctSharp.Generator.Model;
using OcctSharp.Generator.Transformation;
using OcctSharp.Generator.TypeMapping;
namespace OcctSharp.Generator.Tests;
public sealed class TransferRecordsContractTests {
 static BindingDeclaration Declaration(CopiedCollectionOperationContract.Operation op)=>new(op.StableId,op.NativeName,BindingDeclarationKind.Method,op.NativeName.Split("::")[0]+".hxx",1,1){NativeSignature=op.Signature,Access=BindingAccess.Public,ProductModule=OcctProductModule.DataExchange};
 [Fact]public void OnlyExactAuditedAccessibleSignaturesAreAdmitted(){var d=Declaration(TransferRecordsOperationContract.Operations.Values.First(o=>!o.Supporting));Assert.True(TransferRecordsOperationContract.Contains(d));Assert.False(TransferRecordsOperationContract.Contains(d with{NativeSignature=d.NativeSignature+" "}));Assert.False(TransferRecordsOperationContract.Contains(d with{IsDeleted=true}));Assert.False(TransferRecordsOperationContract.Contains(d with{Access=BindingAccess.Private}));Assert.False(TransferRecordsOperationContract.Contains(d with{SupportState=BindingSupportState.Manual}));}
 [Fact]public void UnsafeSdkPathsAndMutableCopiesStayExcluded(){foreach(var name in new[]{"Transfer_ProcessForTransient::ResultOne","Transfer_ProcessForTransient::CheckListOne","Transfer_TransferIterator::SelectResult","Transfer_TransientProcess::TypedSharings","TransferBRep::BRepCheck","XSControl_TransferReader::EntityFromShapeResult","Transfer_ResultFromTransient::FillMap"})Assert.DoesNotContain(TransferRecordsOperationContract.Operations.Values,o=>o.NativeName==name);Assert.DoesNotContain(TransferRecordsOperationContract.Operations.Values,o=>o.NativeName.Split("::") is var n && n[0]==n[1] && o.Signature.Contains("const "+n[0]+" &",StringComparison.Ordinal));}
 [Fact]public void PartialContractCannotPublishAnInflatedManifest(){var d=Declaration(TransferRecordsOperationContract.Operations.Values.First());Assert.Throws<InvalidDataException>(()=>TransferRecordsOperationEmitter.Emit("8.0.1",new BindingModel([d])));}
 [Fact]public void DeterministicOutputExcludesReusedManualIds(){var manual=TransferRecordsOperationContract.Operations.Values.First(o=>o.Supporting);var rows=TransferRecordsOperationContract.Operations.Values.Select(o=>Declaration(o) with{SupportState=o==manual?BindingSupportState.Manual:BindingSupportState.Pending}).ToArray();var a=TransferRecordsOperationEmitter.Emit("8.0.1",new BindingModel(rows));var b=TransferRecordsOperationEmitter.Emit("8.0.1",new BindingModel(rows.Reverse()));Assert.Equal(3,a.Files.Count);Assert.Equal(a.Files.Select(f=>f.Content),b.Files.Select(f=>f.Content));Assert.DoesNotContain(manual.StableId,a.SourceStableIds);Assert.All(a.Files,f=>Assert.Equal(OcctProductModule.DataExchange,f.ProductModule));}
 [Fact]public void PrivateProcessProjectionDoesNotChangeGlobalMapping(){var t=new BindingType("Transfer_IteratorOfProcessForTransient","Transfer_IteratorOfProcessForTransient","Transfer_IteratorOfProcessForTransient","Transfer_IteratorOfProcessForTransient",[new(BindingTypeLayerKind.Value,false)],null,[],false,null);var map=InitialTypeMap.FromModel(new BindingModel([]));var d=Declaration(TransferRecordsOperationContract.Operations.Values.First(o=>o.NativeName=="Transfer_ProcessForTransient::RootResult"));Assert.False(map.TryMap(t,BindingTypeUsage.ReturnValue,out _));Assert.True(TransferRecordsOperationContract.TryMap(d,t,BindingTypeUsage.ReturnValue,map,out var p));Assert.Equal("TM017",p!.RuleId);Assert.False(TransferRecordsOperationContract.TryMap(d with{StableId="unapproved"},t,BindingTypeUsage.ReturnValue,map,out _));}
}
